50	/**
51	 * Wrapper around a {@link ConfigurableEnvironment} that can be used to import and apply
52	 * {@link ConfigData}. Configures the initial set of
53	 * {@link ConfigDataEnvironmentContributors} by wrapping property sources from the Spring
54	 * {@link Environment} and adding the initial set of locations.
55	 * <p>
56	 * The initial locations can be influenced through the {@link #LOCATION_PROPERTY},
57	 * {@value #ADDITIONAL_LOCATION_PROPERTY} and {@value #IMPORT_PROPERTY} properties. If no
58	 * explicit properties are set, the {@link #DEFAULT_SEARCH_LOCATIONS} will be used.
59	 *
60	 * @author Phillip Webb
61	 * @author Madhura Bhave
62	 * @author Nan Chiu
63	 */
64	class ConfigDataEnvironment {
65	
66		/**
67		 * Property used override the imported locations.
68		 */
69		static final String LOCATION_PROPERTY = "spring.config.location";
70	
71		/**
72		 * Property used to provide additional locations to import.
73		 */
74		static final String ADDITIONAL_LOCATION_PROPERTY = "spring.config.additional-location";
75	
76		/**
77		 * Property used to provide additional locations to import.
78		 */
79		static final String IMPORT_PROPERTY = "spring.config.import";
80	
81		/**
82		 * Property used to determine what action to take when a
83		 * {@code ConfigDataNotFoundAction} is thrown.
84		 * @see ConfigDataNotFoundAction
85		 */
86		static final String ON_NOT_FOUND_PROPERTY = "spring.config.on-not-found";
87	
88		/**
89		 * Default search locations used if not {@link #LOCATION_PROPERTY} is found.
90		 */
91		static final ConfigDataLocation[] DEFAULT_SEARCH_LOCATIONS;
92		static {
93			List<ConfigDataLocation> locations = new ArrayList<>();
94			locations.add(ConfigDataLocation.of("optional:classpath:/;optional:classpath:/config/"));
95			locations.add(ConfigDataLocation.of("optional:file:./;optional:file:./config/;optional:file:./config/*/"));
96			DEFAULT_SEARCH_LOCATIONS = locations.toArray(new ConfigDataLocation[0]);
97		}
98	
99		private static final ConfigDataLocation[] EMPTY_LOCATIONS = new ConfigDataLocation[0];
100	
101		private static final Bindable<ConfigDataLocation[]> CONFIG_DATA_LOCATION_ARRAY = Bindable
102			.of(ConfigDataLocation[].class);
103	
104		private static final Bindable<List<String>> STRING_LIST = Bindable.listOf(String.class);
105	
106		private static final BinderOption[] ALLOW_INACTIVE_BINDING = {};
107	
108		private static final BinderOption[] DENY_INACTIVE_BINDING = { BinderOption.FAIL_ON_BIND_TO_INACTIVE_SOURCE };
109	
110		private final DeferredLogFactory logFactory;
111	
112		private final Log logger;
113	
114		private final ConfigDataNotFoundAction notFoundAction;
115	
116		private final ConfigurableBootstrapContext bootstrapContext;
117	
118		private final ConfigurableEnvironment environment;
119	
120		private final ConfigDataLocationResolvers resolvers;
121	
122		private final Collection<String> additionalProfiles;
123	
124		private final ConfigDataEnvironmentUpdateListener environmentUpdateListener;
125	
126		private final ConfigDataLoaders loaders;
127	
128		private final ConfigDataEnvironmentContributors contributors;
129	
130		/**
131		 * Create a new {@link ConfigDataEnvironment} instance.
132		 * @param logFactory the deferred log factory
133		 * @param bootstrapContext the bootstrap context
134		 * @param environment the Spring {@link Environment}.
135		 * @param resourceLoader {@link ResourceLoader} to load resource locations
136		 * @param additionalProfiles any additional profiles to activate
137		 * @param environmentUpdateListener optional
138		 * {@link ConfigDataEnvironmentUpdateListener} that can be used to track
139		 * {@link Environment} updates.
140		 */
141		ConfigDataEnvironment(DeferredLogFactory logFactory, ConfigurableBootstrapContext bootstrapContext,
142				ConfigurableEnvironment environment, ResourceLoader resourceLoader, Collection<String> additionalProfiles,
143				@Nullable ConfigDataEnvironmentUpdateListener environmentUpdateListener) {
144			Binder binder = Binder.get(environment);
145			this.logFactory = logFactory;
146			this.logger = logFactory.getLog(getClass());
147			this.notFoundAction = binder.bind(ON_NOT_FOUND_PROPERTY, ConfigDataNotFoundAction.class)
148				.orElse(ConfigDataNotFoundAction.FAIL);
149			this.bootstrapContext = bootstrapContext;
150			this.environment = environment;
151			this.resolvers = createConfigDataLocationResolvers(logFactory, bootstrapContext, binder, resourceLoader);
152			this.additionalProfiles = additionalProfiles;
153			this.environmentUpdateListener = (environmentUpdateListener != null) ? environmentUpdateListener
154					: ConfigDataEnvironmentUpdateListener.NONE;
155			this.loaders = new ConfigDataLoaders(logFactory, bootstrapContext,
156					SpringFactoriesLoader.forDefaultResourceLocation(resourceLoader.getClassLoader()));
157			this.contributors = createContributors(binder);
158		}
159	
160		protected ConfigDataLocationResolvers createConfigDataLocationResolvers(DeferredLogFactory logFactory,
161				ConfigurableBootstrapContext bootstrapContext, Binder binder, ResourceLoader resourceLoader) {
162			return new ConfigDataLocationResolvers(logFactory, bootstrapContext, binder, resourceLoader,
163					SpringFactoriesLoader.forDefaultResourceLocation(resourceLoader.getClassLoader()));
164		}
165	
166		private ConfigDataEnvironmentContributors createContributors(Binder binder) {
167			this.logger.trace("Building config data environment contributors");
168			MutablePropertySources propertySources = this.environment.getPropertySources();
169			List<ConfigDataEnvironmentContributor> contributors = new ArrayList<>(propertySources.size() + 10);
170			PropertySource<?> defaultPropertySource = null;
171			for (PropertySource<?> propertySource : propertySources) {
172				if (DefaultPropertiesPropertySource.hasMatchingName(propertySource)) {
173					defaultPropertySource = propertySource;
174				}
175				else {
176					this.logger.trace(LogMessage.format("Creating wrapped config data contributor for '%s'",
177							propertySource.getName()));
178					contributors.add(ConfigDataEnvironmentContributor.ofExisting(propertySource,
179							this.environment.getConversionService()));
180				}
181			}
182			contributors.addAll(getInitialImportContributors(binder));
183			if (defaultPropertySource != null) {
184				this.logger.trace("Creating wrapped config data contributor for default property source");
185				contributors.add(ConfigDataEnvironmentContributor.ofExisting(defaultPropertySource,
186						this.environment.getConversionService()));
187			}
188			return createContributors(contributors);
189		}
190	
191		protected ConfigDataEnvironmentContributors createContributors(
192				List<ConfigDataEnvironmentContributor> contributors) {
193			return new ConfigDataEnvironmentContributors(this.logFactory, this.bootstrapContext, contributors,
194					this.environment.getConversionService(), this.environmentUpdateListener);
195		}
196	
197		ConfigDataEnvironmentContributors getContributors() {
198			return this.contributors;
199		}
200	
201		private List<ConfigDataEnvironmentContributor> getInitialImportContributors(Binder binder) {
202			List<ConfigDataEnvironmentContributor> initialContributors = new ArrayList<>();
203			addInitialImportContributors(initialContributors, binder, IMPORT_PROPERTY, EMPTY_LOCATIONS, false);
204			addInitialImportContributors(initialContributors, binder, ADDITIONAL_LOCATION_PROPERTY, EMPTY_LOCATIONS, true);
205			addInitialImportContributors(initialContributors, binder, LOCATION_PROPERTY, DEFAULT_SEARCH_LOCATIONS, true);
206			return initialContributors;
207		}
208	
209		private void addInitialImportContributors(List<ConfigDataEnvironmentContributor> initialContributors, Binder binder,
210				String propertyName, ConfigDataLocation[] defaultValue, boolean registerIndividually) {
211			ConfigDataLocation[] locations = binder.bind(propertyName, CONFIG_DATA_LOCATION_ARRAY).orElse(defaultValue);
212			if (registerIndividually) {
213				for (int i = locations.length - 1; i >= 0; i--) {
214					addInitialImportContributors(initialContributors, List.of(locations[i]));
215				}
216			}
217			else {
218				addInitialImportContributors(initialContributors, List.of(locations));
219			}
220		}
221	
222		private void addInitialImportContributors(List<ConfigDataEnvironmentContributor> initialContributors,
223				List<ConfigDataLocation> locations) {
224			if (!locations.isEmpty()) {
225				this.logger.trace(LogMessage.format("Adding initial config data import from locations %s", locations));
226				ConfigDataEnvironmentContributor contributor = ConfigDataEnvironmentContributor.ofInitialImports(locations,
227						this.environment.getConversionService());
228				initialContributors.add(contributor);
229			}
230		}
231	
232		/**
233		 * Process all contributions and apply any newly imported property sources to the
234		 * {@link Environment}.
235		 */
236		void processAndApply() {
237			ConfigDataImporter importer = new ConfigDataImporter(this.logFactory, this.notFoundAction, this.resolvers,
238					this.loaders);
239			registerBootstrapBinder(this.contributors, null, DENY_INACTIVE_BINDING);
240			ConfigDataEnvironmentContributors contributors = processInitial(this.contributors, importer);
241			ConfigDataActivationContext activationContext = createActivationContext(
242					contributors.getBinder(null, BinderOption.FAIL_ON_BIND_TO_INACTIVE_SOURCE));
243			contributors = processWithoutProfiles(contributors, importer, activationContext);
244			activationContext = withProfiles(contributors, activationContext);
245			contributors = processWithProfiles(contributors, importer, activationContext);
246			applyToEnvironment(contributors, activationContext, importer.getLoadedLocations(),
247					importer.getOptionalLocations());
248		}
249	
250		private ConfigDataEnvironmentContributors processInitial(ConfigDataEnvironmentContributors contributors,
251				ConfigDataImporter importer) {
252			this.logger.trace("Processing initial config data environment contributors without activation context");
253			contributors = contributors.withProcessedImports(importer, null);
254			registerBootstrapBinder(contributors, null, DENY_INACTIVE_BINDING);
255			return contributors;
256		}
257	
258		private ConfigDataActivationContext createActivationContext(Binder initialBinder) {
259			this.logger.trace("Creating config data activation context from initial contributions");
260			try {
261				return new ConfigDataActivationContext(this.environment, initialBinder);
262			}
263			catch (BindException ex) {
264				if (ex.getCause() instanceof InactiveConfigDataAccessException inactiveException) {
265					throw inactiveException;
266				}
267				throw ex;
268			}
269		}
270	
271		private ConfigDataEnvironmentContributors processWithoutProfiles(ConfigDataEnvironmentContributors contributors,
272				ConfigDataImporter importer, ConfigDataActivationContext activationContext) {
273			this.logger.trace("Processing config data environment contributors with initial activation context");
274			contributors = contributors.withProcessedImports(importer, activationContext);
275			registerBootstrapBinder(contributors, activationContext, DENY_INACTIVE_BINDING);
276			return contributors;
277		}
278	
279		private ConfigDataActivationContext withProfiles(ConfigDataEnvironmentContributors contributors,
280				ConfigDataActivationContext activationContext) {
281			this.logger.trace("Deducing profiles from current config data environment contributors");
282			Binder binder = contributors.getBinder(activationContext,
283					(contributor) -> !contributor.hasConfigDataOption(ConfigData.Option.IGNORE_PROFILES),
284					BinderOption.FAIL_ON_BIND_TO_INACTIVE_SOURCE);
285			try {
286				Set<String> additionalProfiles = new LinkedHashSet<>(this.additionalProfiles);
287				additionalProfiles.addAll(getIncludedProfiles(contributors, activationContext));
288				Profiles profiles = new Profiles(this.environment, binder, additionalProfiles);
289				return activationContext.withProfiles(profiles);
290			}
291			catch (BindException ex) {
292				if (ex.getCause() instanceof InactiveConfigDataAccessException inactiveException) {
293					throw inactiveException;
294				}
295				throw ex;
296			}
297		}
298	
299		private Collection<? extends String> getIncludedProfiles(ConfigDataEnvironmentContributors contributors,
300				ConfigDataActivationContext activationContext) {
301			PlaceholdersResolver placeholdersResolver = new ConfigDataEnvironmentContributorPlaceholdersResolver(
302					contributors, activationContext, null, true, this.environment.getConversionService());
303			Set<String> result = new LinkedHashSet<>();
304			for (ConfigDataEnvironmentContributor contributor : contributors) {
305				ConfigurationPropertySource source = contributor.getConfigurationPropertySource();
306				if (source != null && !contributor.hasConfigDataOption(ConfigData.Option.IGNORE_PROFILES)) {
307					Binder binder = new Binder(Collections.singleton(source), placeholdersResolver);
308					binder.bind(Profiles.INCLUDE_PROFILES, STRING_LIST, ProfilesValidator.get(binder))
309						.ifBound((includes) -> {
310							if (!contributor.isActive(activationContext)) {
311								InactiveConfigDataAccessException.throwIfPropertyFound(contributor,
312										Profiles.INCLUDE_PROFILES);
313								InactiveConfigDataAccessException.throwIfPropertyFound(contributor,
314										Profiles.INCLUDE_PROFILES.append("[0]"));
315							}
316							result.addAll(includes);
317						});
318				}
319			}
320			return result;
321		}
322	
323		private ConfigDataEnvironmentContributors processWithProfiles(ConfigDataEnvironmentContributors contributors,
324				ConfigDataImporter importer, ConfigDataActivationContext activationContext) {
325			this.logger.trace("Processing config data environment contributors with profile activation context");
326			contributors = contributors.withProcessedImports(importer, activationContext);
327			registerBootstrapBinder(contributors, activationContext, ALLOW_INACTIVE_BINDING);
328			return contributors;
329		}
330	
331		private void registerBootstrapBinder(ConfigDataEnvironmentContributors contributors,
332				@Nullable ConfigDataActivationContext activationContext, BinderOption... binderOptions) {
333			this.bootstrapContext.register(Binder.class,
334					InstanceSupplier.from(() -> contributors.getBinder(activationContext, binderOptions))
335						.withScope(Scope.PROTOTYPE));
336		}
337	
338		private void applyToEnvironment(ConfigDataEnvironmentContributors contributors,
339				ConfigDataActivationContext activationContext, Set<ConfigDataLocation> loadedLocations,
340				Set<ConfigDataLocation> optionalLocations) {
341			checkForInvalidProperties(contributors);
342			checkMandatoryLocations(contributors, activationContext, loadedLocations, optionalLocations);
343			MutablePropertySources propertySources = this.environment.getPropertySources();
344			applyContributor(contributors, activationContext, propertySources);
345			DefaultPropertiesPropertySource.moveToEnd(propertySources);
346			Profiles profiles = activationContext.getProfiles();
347			Assert.state(profiles != null, "'profiles' must not be null");
348			this.logger.trace(LogMessage.format("Setting default profiles: %s", profiles.getDefault()));
349			this.environment.setDefaultProfiles(StringUtils.toStringArray(profiles.getDefault()));
350			this.logger.trace(LogMessage.format("Setting active profiles: %s", profiles.getActive()));
351			this.environment.setActiveProfiles(StringUtils.toStringArray(profiles.getActive()));
352			this.environmentUpdateListener.onSetProfiles(profiles);
353		}
354	
355		private void applyContributor(ConfigDataEnvironmentContributors contributors,
356				ConfigDataActivationContext activationContext, MutablePropertySources propertySources) {
357			this.logger.trace("Applying config data environment contributions");
358			for (ConfigDataEnvironmentContributor contributor : contributors) {
359				PropertySource<?> propertySource = contributor.getPropertySource();
360				if (contributor.getKind() == ConfigDataEnvironmentContributor.Kind.BOUND_IMPORT && propertySource != null) {
361					if (!contributor.isActive(activationContext)) {
362						this.logger
363							.trace(LogMessage.format("Skipping inactive property source '%s'", propertySource.getName()));
364					}
365					else {
366						this.logger
367							.trace(LogMessage.format("Adding imported property source '%s'", propertySource.getName()));
368						propertySources.addLast(propertySource);
369						this.environmentUpdateListener.onPropertySourceAdded(propertySource, contributor.getLocation(),
370								contributor.getResource());
371					}
372				}
373			}
374		}
375	
376		private void checkForInvalidProperties(ConfigDataEnvironmentContributors contributors) {
377			for (ConfigDataEnvironmentContributor contributor : contributors) {
378				InvalidConfigDataPropertyException.throwIfPropertyFound(contributor);
379			}
380		}
381	
382		private void checkMandatoryLocations(ConfigDataEnvironmentContributors contributors,
383				ConfigDataActivationContext activationContext, Set<ConfigDataLocation> loadedLocations,
384				Set<ConfigDataLocation> optionalLocations) {
385			Set<ConfigDataLocation> mandatoryLocations = new LinkedHashSet<>();
386			for (ConfigDataEnvironmentContributor contributor : contributors) {
387				if (contributor.isActive(activationContext)) {
388					mandatoryLocations.addAll(getMandatoryImports(contributor));
389				}
390			}
391			for (ConfigDataEnvironmentContributor contributor : contributors) {
392				if (contributor.getLocation() != null) {
393					mandatoryLocations.remove(contributor.getLocation());
394				}
395			}
396			mandatoryLocations.removeAll(loadedLocations);
397			mandatoryLocations.removeAll(optionalLocations);
398			if (!mandatoryLocations.isEmpty()) {
399				for (ConfigDataLocation mandatoryLocation : mandatoryLocations) {
400					this.notFoundAction.handle(this.logger, new ConfigDataLocationNotFoundException(mandatoryLocation));
401				}
402			}
403		}
404	
405		private Set<ConfigDataLocation> getMandatoryImports(ConfigDataEnvironmentContributor contributor) {
406			List<ConfigDataLocation> imports = contributor.getImports();
407			Set<ConfigDataLocation> mandatoryLocations = new LinkedHashSet<>(imports.size());
408			for (ConfigDataLocation location : imports) {
409				if (!location.isOptional()) {
410					mandatoryLocations.add(location);
411				}
412			}
413			return mandatoryLocations;
414		}
415	
416	}
