51	/**
52	 * Utility to handle any conversion needed during binding. This class is not thread-safe
53	 * and so a new instance is created for each top-level bind.
54	 *
55	 * @author Phillip Webb
56	 * @author Andy Wilkinson
57	 */
58	final class BindConverter {
59	
60		private static @Nullable BindConverter sharedInstance;
61	
62		private final List<ConversionService> delegates;
63	
64		private BindConverter(@Nullable List<ConversionService> conversionServices,
65				@Nullable Consumer<PropertyEditorRegistry> propertyEditorInitializer) {
66			List<ConversionService> delegates = new ArrayList<>();
67			delegates.add(new TypeConverterConversionService(propertyEditorInitializer));
68			boolean hasApplication = false;
69			if (!CollectionUtils.isEmpty(conversionServices)) {
70				for (ConversionService conversionService : conversionServices) {
71					delegates.add(conversionService);
72					hasApplication = hasApplication || conversionService instanceof ApplicationConversionService;
73				}
74			}
75			if (!hasApplication) {
76				delegates.add(ApplicationConversionService.getSharedInstance());
77			}
78			this.delegates = Collections.unmodifiableList(delegates);
79		}
80	
81		boolean canConvert(@Nullable Object source, ResolvableType targetType, Annotation... targetAnnotations) {
82			return canConvert(TypeDescriptor.forObject(source),
83					new ResolvableTypeDescriptor(targetType, targetAnnotations));
84		}
85	
86		private boolean canConvert(@Nullable TypeDescriptor sourceType, TypeDescriptor targetType) {
87			for (ConversionService service : this.delegates) {
88				if (service.canConvert(sourceType, targetType)) {
89					return true;
90				}
91			}
92			return false;
93		}
94	
95		<T> @Nullable T convert(@Nullable Object source, Bindable<T> target) {
96			return convert(source, target.getType(), target.getAnnotations());
97		}
98	
99		@SuppressWarnings("unchecked")
100		<T> @Nullable T convert(@Nullable Object source, ResolvableType targetType, Annotation... targetAnnotations) {
101			TypeDescriptor sourceType = (source != null) ? TypeDescriptor.forObject(source) : null;
102			return (T) convert(source, sourceType, new ResolvableTypeDescriptor(targetType, targetAnnotations));
103		}
104	
105		private @Nullable Object convert(@Nullable Object source, @Nullable TypeDescriptor sourceType,
106				TypeDescriptor targetType) {
107			ConversionException failure = null;
108			for (ConversionService delegate : this.delegates) {
109				try {
110					if (delegate.canConvert(sourceType, targetType)) {
111						return delegate.convert(source, sourceType, targetType);
112					}
113				}
114				catch (ConversionException ex) {
115					if (failure == null && ex instanceof ConversionFailedException) {
116						failure = ex;
117					}
118				}
119			}
120			if (source == null) {
121				return null;
122			}
123			throw (failure != null) ? failure : new ConverterNotFoundException(sourceType, targetType);
124		}
125	
126		static BindConverter get(@Nullable List<ConversionService> conversionServices,
127				@Nullable Consumer<PropertyEditorRegistry> propertyEditorInitializer) {
128			boolean sharedApplicationConversionService = (conversionServices == null) || (conversionServices.size() == 1
129					&& conversionServices.get(0) == ApplicationConversionService.getSharedInstance());
130			if (propertyEditorInitializer == null && sharedApplicationConversionService) {
131				return getSharedInstance();
132			}
133			return new BindConverter(conversionServices, propertyEditorInitializer);
134		}
135	
136		private static BindConverter getSharedInstance() {
137			if (sharedInstance == null) {
138				sharedInstance = new BindConverter(null, null);
139			}
140			return sharedInstance;
141		}
142	
143		/**
144		 * A {@link TypeDescriptor} backed by a {@link ResolvableType}.
145		 */
146		private static class ResolvableTypeDescriptor extends TypeDescriptor {
147	
148			ResolvableTypeDescriptor(ResolvableType resolvableType, Annotation[] annotations) {
149				super(resolvableType, null, annotations);
150			}
151	
152		}
153	
154		/**
155		 * A {@link ConversionService} implementation that delegates to a
156		 * {@link SimpleTypeConverter}. Allows {@link PropertyEditor} based conversion for
157		 * simple types, arrays and collections.
158		 */
159		private static class TypeConverterConversionService extends GenericConversionService {
160	
161			TypeConverterConversionService(@Nullable Consumer<PropertyEditorRegistry> initializer) {
162				ApplicationConversionService.addDelimitedStringConverters(this);
163				addConverter(new TypeConverterConverter(initializer));
164			}
165	
166			@Override
167			public boolean canConvert(@Nullable TypeDescriptor sourceType, TypeDescriptor targetType) {
168				// Prefer conversion service to handle things like String to char[].
169				if (isPrimitiveArray(targetType)) {
170					return false;
171				}
172				return super.canConvert(sourceType, targetType);
173			}
174	
175			private static boolean isPrimitiveArray(TypeDescriptor targetType) {
176				if (!targetType.isArray()) {
177					return false;
178				}
179				TypeDescriptor elementTypeDescriptor = targetType.getElementTypeDescriptor();
180				Assert.state(elementTypeDescriptor != null, "'elementTypeDescriptor' must not be null");
181				return elementTypeDescriptor.isPrimitive();
182			}
183	
184		}
185	
186		/**
187		 * {@link ConditionalGenericConverter} that delegates to {@link SimpleTypeConverter}.
188		 */
189		private static class TypeConverterConverter implements ConditionalGenericConverter {
190	
191			private static final Set<Class<?>> EXCLUDED_EDITORS;
192			static {
193				Set<Class<?>> excluded = new HashSet<>();
194				excluded.add(CustomNumberEditor.class);
195				excluded.add(CustomBooleanEditor.class);
196				excluded.add(FileEditor.class);
197				EXCLUDED_EDITORS = Collections.unmodifiableSet(excluded);
198			}
199	
200			private final @Nullable Consumer<PropertyEditorRegistry> initializer;
201	
202			// SimpleTypeConverter is not thread-safe to use for conversion but we can use it
203			// in a thread-safe way to check if conversion is possible.
204			private final SimpleTypeConverter matchesOnlyTypeConverter;
205	
206			TypeConverterConverter(@Nullable Consumer<PropertyEditorRegistry> initializer) {
207				this.initializer = initializer;
208				this.matchesOnlyTypeConverter = createTypeConverter();
209			}
210	
211			@Override
212			public Set<ConvertiblePair> getConvertibleTypes() {
213				return Set.of(new ConvertiblePair(String.class, Object.class),
214						new ConvertiblePair(String.class, Resource[].class),
215						new ConvertiblePair(String.class, Collection.class));
216			}
217	
218			@Override
219			public boolean matches(TypeDescriptor sourceType, TypeDescriptor targetType) {
220				Class<?> type = targetType.getType();
221				if (type == null || type == Object.class || Map.class.isAssignableFrom(type)) {
222					return false;
223				}
224				if (Collection.class.isAssignableFrom(type)) {
225					TypeDescriptor elementType = targetType.getElementTypeDescriptor();
226					if (elementType == null || (!Resource.class.isAssignableFrom(elementType.getType()))) {
227						return false;
228					}
229				}
230				PropertyEditor editor = this.matchesOnlyTypeConverter.getDefaultEditor(type);
231				if (editor == null) {
232					editor = this.matchesOnlyTypeConverter.findCustomEditor(type, null);
233				}
234				if (editor == null && String.class != type) {
235					editor = BeanUtils.findEditorByConvention(type);
236				}
237				return (editor != null && !EXCLUDED_EDITORS.contains(editor.getClass()));
238			}
239	
240			@Override
241			public @Nullable Object convert(@Nullable Object source, TypeDescriptor sourceType, TypeDescriptor targetType) {
242				return createTypeConverter().convertIfNecessary(source, targetType.getType(), targetType);
243			}
244	
245			private SimpleTypeConverter createTypeConverter() {
246				SimpleTypeConverter typeConverter = new SimpleTypeConverter();
247				if (this.initializer != null) {
248					this.initializer.accept(typeConverter);
249				}
250				return typeConverter;
251			}
252	
253		}
254	
255	}
