36	/**
37	 * Abstract base class for {@link LoggingSystem} implementations.
38	 *
39	 * @author Phillip Webb
40	 * @author Dave Syer
41	 * @since 1.0.0
42	 */
43	public abstract class AbstractLoggingSystem extends LoggingSystem {
44	
45		protected static final Comparator<LoggerConfiguration> CONFIGURATION_COMPARATOR = new LoggerConfigurationComparator(
46				ROOT_LOGGER_NAME);
47	
48		private final ClassLoader classLoader;
49	
50		public AbstractLoggingSystem(ClassLoader classLoader) {
51			this.classLoader = classLoader;
52		}
53	
54		@Override
55		public void beforeInitialize() {
56		}
57	
58		@Override
59		public void initialize(LoggingInitializationContext initializationContext, @Nullable String configLocation,
60				@Nullable LogFile logFile) {
61			if (StringUtils.hasLength(configLocation)) {
62				initializeWithSpecificConfig(initializationContext, configLocation, logFile);
63				return;
64			}
65			initializeWithConventions(initializationContext, logFile);
66		}
67	
68		private void initializeWithSpecificConfig(LoggingInitializationContext initializationContext, String configLocation,
69				@Nullable LogFile logFile) {
70			configLocation = SystemPropertyUtils.resolvePlaceholders(configLocation);
71			loadConfiguration(initializationContext, configLocation, logFile);
72		}
73	
74		private void initializeWithConventions(LoggingInitializationContext initializationContext,
75				@Nullable LogFile logFile) {
76			String config = getSelfInitializationConfig();
77			if (config != null && logFile == null) {
78				// self initialization has occurred, reinitialize in case of property changes
79				reinitialize(initializationContext);
80				return;
81			}
82			if (config == null) {
83				config = getSpringInitializationConfig();
84			}
85			if (config != null) {
86				loadConfiguration(initializationContext, config, logFile);
87				return;
88			}
89			loadDefaults(initializationContext, logFile);
90		}
91	
92		/**
93		 * Return any self initialization config that has been applied. By default this method
94		 * checks {@link #getStandardConfigLocations()} and assumes that any file that exists
95		 * will have been applied.
96		 * @return the self initialization config or {@code null}
97		 */
98		protected @Nullable String getSelfInitializationConfig() {
99			return findConfig(getStandardConfigLocations());
100		}
101	
102		/**
103		 * Return any spring specific initialization config that should be applied. By default
104		 * this method checks {@link #getSpringConfigLocations()}.
105		 * @return the spring initialization config or {@code null}
106		 */
107		protected @Nullable String getSpringInitializationConfig() {
108			return findConfig(getSpringConfigLocations());
109		}
110	
111		private @Nullable String findConfig(String[] locations) {
112			for (String location : locations) {
113				ClassPathResource resource = new ClassPathResource(location, this.classLoader);
114				if (resource.exists()) {
115					return "classpath:" + location;
116				}
117			}
118			return null;
119		}
120	
121		/**
122		 * Return the standard config locations for this system.
123		 * @return the standard config locations
124		 * @see #getSelfInitializationConfig()
125		 */
126		protected abstract String[] getStandardConfigLocations();
127	
128		/**
129		 * Return the spring config locations for this system. By default this method returns
130		 * a set of locations based on {@link #getStandardConfigLocations()}.
131		 * @return the spring config locations
132		 * @see #getSpringInitializationConfig()
133		 */
134		protected String[] getSpringConfigLocations() {
135			String[] locations = getStandardConfigLocations();
136			for (int i = 0; i < locations.length; i++) {
137				String extension = StringUtils.getFilenameExtension(locations[i]);
138				int extensionLength = (extension != null) ? (extension.length() + 1) : 0;
139				locations[i] = locations[i].substring(0, locations[i].length() - extensionLength) + "-spring." + extension;
140			}
141			return locations;
142		}
143	
144		/**
145		 * Load sensible defaults for the logging system.
146		 * @param initializationContext the logging initialization context
147		 * @param logFile the file to load or {@code null} if no log file is to be written
148		 */
149		protected abstract void loadDefaults(LoggingInitializationContext initializationContext, @Nullable LogFile logFile);
150	
151		/**
152		 * Load a specific configuration.
153		 * @param initializationContext the logging initialization context
154		 * @param location the location of the configuration to load (never {@code null})
155		 * @param logFile the file to load or {@code null} if no log file is to be written
156		 */
157		protected abstract void loadConfiguration(LoggingInitializationContext initializationContext, String location,
158				@Nullable LogFile logFile);
159	
160		/**
161		 * Reinitialize the logging system if required. Called when
162		 * {@link #getSelfInitializationConfig()} is used and the log file hasn't changed. May
163		 * be used to reload configuration (for example to pick up additional System
164		 * properties).
165		 * @param initializationContext the logging initialization context
166		 */
167		protected void reinitialize(LoggingInitializationContext initializationContext) {
168		}
169	
170		protected final ClassLoader getClassLoader() {
171			return this.classLoader;
172		}
173	
174		protected final String getPackagedConfigFile(String fileName) {
175			String defaultPath = ClassUtils.getPackageName(getClass());
176			defaultPath = defaultPath.replace('.', '/');
177			defaultPath = defaultPath + "/" + fileName;
178			defaultPath = "classpath:" + defaultPath;
179			return defaultPath;
180		}
181	
182		protected final void applySystemProperties(Environment environment, @Nullable LogFile logFile) {
183			new LoggingSystemProperties(environment, getDefaultValueResolver(environment), null).apply(logFile);
184		}
185	
186		/**
187		 * Return the default value resolver to use when resolving system properties.
188		 * @param environment the environment
189		 * @return the default value resolver
190		 * @since 3.2.0
191		 */
192		protected Function<@Nullable String, @Nullable String> getDefaultValueResolver(Environment environment) {
193			String defaultLogCorrelationPattern = getDefaultLogCorrelationPattern();
194			return (name) -> {
195				String applicationPropertyName = LoggingSystemProperty.CORRELATION_PATTERN.getApplicationPropertyName();
196				Assert.state(applicationPropertyName != null, "applicationPropertyName must not be null");
197				if (StringUtils.hasLength(defaultLogCorrelationPattern) && applicationPropertyName.equals(name)
198						&& environment.getProperty(LoggingSystem.EXPECT_CORRELATION_ID_PROPERTY, Boolean.class, false)) {
199					return defaultLogCorrelationPattern;
200				}
201				return null;
202			};
203		}
204	
205		/**
206		 * Return the default log correlation pattern or {@code null} if log correlation
207		 * patterns are not supported.
208		 * @return the default log correlation pattern
209		 * @since 3.2.0
210		 */
211		protected @Nullable String getDefaultLogCorrelationPattern() {
212			return null;
213		}
214	
215		/**
216		 * Maintains a mapping between native levels and {@link LogLevel}.
217		 *
218		 * @param <T> the native level type
219		 */
220		protected static class LogLevels<T> {
221	
222			private final Map<LogLevel, T> systemToNative;
223	
224			private final Map<T, LogLevel> nativeToSystem;
225	
226			public LogLevels() {
227				this.systemToNative = new EnumMap<>(LogLevel.class);
228				this.nativeToSystem = new HashMap<>();
229			}
230	
231			public void map(LogLevel system, T nativeLevel) {
232				this.systemToNative.putIfAbsent(system, nativeLevel);
233				this.nativeToSystem.putIfAbsent(nativeLevel, system);
234			}
235	
236			public @Nullable LogLevel convertNativeToSystem(T level) {
237				return this.nativeToSystem.get(level);
238			}
239	
240			public @Nullable T convertSystemToNative(@Nullable LogLevel level) {
241				return this.systemToNative.get(level);
242			}
243	
244			public Set<LogLevel> getSupported() {
245				return new LinkedHashSet<>(this.nativeToSystem.values());
246			}
247	
248		}
249	
250	}
