380		private void prepareContext(DefaultBootstrapContext bootstrapContext, ConfigurableApplicationContext context,
381				ConfigurableEnvironment environment, SpringApplicationRunListeners listeners,
382				ApplicationArguments applicationArguments, @Nullable Banner printedBanner) {
383			context.setEnvironment(environment);
384			postProcessApplicationContext(context);
385			addAotGeneratedInitializerIfNecessary(this.initializers);
386			ConfigurableListableBeanFactory beanFactory = context.getBeanFactory();
387			configureBeanFactory(beanFactory);
388			applyInitializers(context);
389			listeners.contextPrepared(context);
390			bootstrapContext.close(context);
391			if (this.properties.isLogStartupInfo()) {
392				logStartupInfo(context);
393				logStartupProfileInfo(context);
394			}
395			// Add boot specific singleton beans
396			beanFactory.registerSingleton("springApplicationArguments", applicationArguments);
397			if (printedBanner != null) {
398				beanFactory.registerSingleton("springBootBanner", printedBanner);
399			}
400			if (this.properties.isLazyInitialization()) {
401				context.addBeanFactoryPostProcessor(new LazyInitializationBeanFactoryPostProcessor());
402			}
403			if (this.properties.isKeepAlive()) {
404				context.addApplicationListener(new KeepAlive());
405			}
406			context.addBeanFactoryPostProcessor(new PropertySourceOrderingBeanFactoryPostProcessor(context));
407			if (!AotDetector.useGeneratedArtifacts()) {
408				// Load the sources
409				Set<Object> sources = getAllSources();
410				Assert.state(!ObjectUtils.isEmpty(sources), "No sources defined");
411				load(context, sources.toArray(new Object[0]));
412			}
413			listeners.contextLoaded(context);
414		}
