416		private void configureBeanFactory(ConfigurableListableBeanFactory beanFactory) {
417			if (beanFactory instanceof AbstractAutowireCapableBeanFactory autowireCapableBeanFactory) {
418				autowireCapableBeanFactory.setAllowCircularReferences(this.properties.isAllowCircularReferences());
419				if (beanFactory instanceof DefaultListableBeanFactory listableBeanFactory) {
420					listableBeanFactory.setAllowBeanDefinitionOverriding(this.properties.isAllowBeanDefinitionOverriding());
421				}
422			}
423		}
