425		private void addAotGeneratedInitializerIfNecessary(List<ApplicationContextInitializer<?>> initializers) {
426			if (AotDetector.useGeneratedArtifacts()) {
427				List<ApplicationContextInitializer<?>> aotInitializers = new ArrayList<>(
428						initializers.stream().filter(AotApplicationContextInitializer.class::isInstance).toList());
429				if (aotInitializers.isEmpty()) {
430					Assert.state(this.mainApplicationClass != null, "No application main class found");
431					String initializerClassName = this.mainApplicationClass.getName() + "__ApplicationContextInitializer";
432					if (!ClassUtils.isPresent(initializerClassName, getClassLoader())) {
433						throw new AotInitializerNotFoundException(this.mainApplicationClass, initializerClassName);
434					}
435					aotInitializers.add(AotApplicationContextInitializer.forInitializerClasses(initializerClassName));
436				}
437				initializers.removeAll(aotInitializers);
438				initializers.addAll(0, aotInitializers);
439			}
440			if (NativeDetector.inNativeImage()) {
441				NativeImageRequirementsException.throwIfNotMet();
442			}
443		}
