457		private SpringApplicationRunListeners getRunListeners(String[] args) {
458			ArgumentResolver argumentResolver = ArgumentResolver.of(SpringApplication.class, this);
459			argumentResolver = argumentResolver.and(String[].class, args);
460			List<SpringApplicationRunListener> listeners = getSpringFactoriesInstances(SpringApplicationRunListener.class,
461					argumentResolver);
462			SpringApplicationHook hook = applicationHook.get();
463			SpringApplicationRunListener hookListener = (hook != null) ? hook.getRunListener(this) : null;
464			if (hookListener != null) {
465				listeners = new ArrayList<>(listeners);
466				listeners.add(hookListener);
467			}
468			return new SpringApplicationRunListeners(logger, listeners, this.applicationStartup);
469		}
