479		private ConfigurableEnvironment getOrCreateEnvironment() {
480			if (this.environment != null) {
481				return this.environment;
482			}
483			WebApplicationType webApplicationType = this.properties.getWebApplicationType();
484			ConfigurableEnvironment environment = this.applicationContextFactory.createEnvironment(webApplicationType);
485			if (environment == null && this.applicationContextFactory != ApplicationContextFactory.DEFAULT) {
486				environment = ApplicationContextFactory.DEFAULT.createEnvironment(webApplicationType);
487			}
488			return (environment != null) ? environment : new ApplicationEnvironment();
489		}
