511		 * Add, remove or re-order any {@link PropertySource}s in this application's
512		 * environment.
513		 * @param environment this application's environment
514		 * @param args arguments passed to the {@code run} method
515		 * @see #configureEnvironment(ConfigurableEnvironment, String[])
516		 */
517		protected void configurePropertySources(ConfigurableEnvironment environment, String[] args) {
518			MutablePropertySources sources = environment.getPropertySources();
519			if (!CollectionUtils.isEmpty(this.defaultProperties)) {
520				DefaultPropertiesPropertySource.addOrMerge(this.defaultProperties, sources);
521			}
522			if (this.addCommandLineProperties && args.length > 0) {
523				String name = CommandLinePropertySource.COMMAND_LINE_PROPERTY_SOURCE_NAME;
524				PropertySource<?> source = sources.get(name);
525				if (source != null) {
526					CompositePropertySource composite = new CompositePropertySource(name);
527					composite
528						.addPropertySource(new SimpleCommandLinePropertySource("springApplicationCommandLineArgs", args));
529					composite.addPropertySource(source);
530					sources.replace(name, composite);
531				}
532				else {
533					sources.addFirst(new SimpleCommandLinePropertySource(args));
534				}
535			}
536			environment.getPropertySources().addLast(new ApplicationInfoPropertySource(this.mainApplicationClass));
537		}
