649		protected void logStartupProfileInfo(ConfigurableApplicationContext context) {
650			Log log = getApplicationLog();
651			if (log.isInfoEnabled()) {
652				List<String> activeProfiles = quoteProfiles(context.getEnvironment().getActiveProfiles());
653				if (ObjectUtils.isEmpty(activeProfiles)) {
654					List<String> defaultProfiles = quoteProfiles(context.getEnvironment().getDefaultProfiles());
655					String message = String.format("%s default %s: ", defaultProfiles.size(),
656							(defaultProfiles.size() <= 1) ? "profile" : "profiles");
657					log.info("No active profile set, falling back to " + message
658							+ StringUtils.collectionToDelimitedString(defaultProfiles, ", "));
659				}
660				else {
661					String message = (activeProfiles.size() == 1) ? "1 profile is active: "
662							: activeProfiles.size() + " profiles are active: ";
663					log.info("The following " + message + StringUtils.collectionToDelimitedString(activeProfiles, ", "));
664				}
665			}
666		}
