772		private void callRunners(ConfigurableApplicationContext context, ApplicationArguments args) {
773			ConfigurableListableBeanFactory beanFactory = context.getBeanFactory();
774			String[] beanNames = beanFactory.getBeanNamesForType(Runner.class);
775			Map<Runner, String> instancesToBeanNames = new IdentityHashMap<>();
776			for (String beanName : beanNames) {
777				instancesToBeanNames.put(beanFactory.getBean(beanName, Runner.class), beanName);
778			}
779			Comparator<Object> comparator = getOrderComparator(beanFactory)
780				.withSourceProvider(new FactoryAwareOrderSourceProvider(beanFactory, instancesToBeanNames));
781			instancesToBeanNames.keySet().stream().sorted(comparator).forEach((runner) -> callRunner(runner, args));
782		}
783	
784		private OrderComparator getOrderComparator(ConfigurableListableBeanFactory beanFactory) {
785			Comparator<?> dependencyComparator = (beanFactory instanceof DefaultListableBeanFactory defaultListableBeanFactory)
786					? defaultListableBeanFactory.getDependencyComparator() : null;
787			return (dependencyComparator instanceof OrderComparator orderComparator) ? orderComparator
788					: AnnotationAwareOrderComparator.INSTANCE;
789		}
790	
791		private void callRunner(Runner runner, ApplicationArguments args) {
792			if (runner instanceof ApplicationRunner) {
793				callRunner(ApplicationRunner.class, runner, (applicationRunner) -> applicationRunner.run(args));
794			}
795			if (runner instanceof CommandLineRunner) {
796				callRunner(CommandLineRunner.class, runner,
797						(commandLineRunner) -> commandLineRunner.run(args.getSourceArgs()));
798			}
799		}
