801		@SuppressWarnings("unchecked")
802		private <R extends Runner> void callRunner(Class<R> type, Runner runner, ThrowingConsumer<R> call) {
803			call.throwing(
804					(message, ex) -> new IllegalStateException("Failed to execute " + ClassUtils.getShortName(type), ex))
805				.accept((R) runner);
806		}
