808		private RuntimeException handleRunFailure(@Nullable ConfigurableApplicationContext context, Throwable exception,
809				@Nullable SpringApplicationRunListeners listeners) {
810			if (exception instanceof AbandonedRunException abandonedRunException) {
811				return abandonedRunException;
812			}
813			try {
814				try {
815					handleExitCode(context, exception);
816					if (listeners != null) {
817						listeners.failed(context, exception);
818					}
819				}
820				finally {
821					reportFailure(getExceptionReporters(context), exception);
822					if (context != null) {
823						context.close();
824						shutdownHook.deregisterFailedApplicationContext(context);
825					}
826				}
827			}
828			catch (Exception ex) {
829				logger.warn("Unable to close ApplicationContext", ex);
830			}
831			return (exception instanceof RuntimeException runtimeException) ? runtimeException
832					: new IllegalStateException(exception);
833		}
