835		private Collection<SpringBootExceptionReporter> getExceptionReporters(
836				@Nullable ConfigurableApplicationContext context) {
837			try {
838				ArgumentResolver argumentResolver = (context != null)
839						? ArgumentResolver.of(ConfigurableApplicationContext.class, context) : ArgumentResolver.none();
840				return getSpringFactoriesInstances(SpringBootExceptionReporter.class, argumentResolver);
841			}
842			catch (Throwable ex) {
843				return Collections.emptyList();
844			}
845		}
846	
847		private void reportFailure(Collection<SpringBootExceptionReporter> exceptionReporters, Throwable failure) {
848			try {
849				for (SpringBootExceptionReporter reporter : exceptionReporters) {
850					if (reporter.reportException(failure)) {
851						registerLoggedException(failure);
852						return;
853					}
854				}
855			}
856			catch (Throwable ex) {
857				// Continue with normal handling of the original failure
858			}
859			if (logger.isErrorEnabled()) {
860				if (NativeDetector.inNativeImage()) {
861					// Depending on how early the failure was, logging may not work in a
862					// native image so we output the stack trace directly to System.out
863					// instead.
864					System.out.println("Application run failed");
865					failure.printStackTrace(System.out);
866				}
867				else {
868					logger.error("Application run failed", failure);
869				}
870				registerLoggedException(failure);
871			}
872		}
