886		private void handleExitCode(@Nullable ConfigurableApplicationContext context, Throwable exception) {
887			int exitCode = getExitCodeFromException(context, exception);
888			if (exitCode != 0) {
889				if (context != null) {
890					context.publishEvent(new ExitCodeEvent(context, exitCode));
891				}
892				SpringBootExceptionHandler handler = getSpringBootExceptionHandler();
893				if (handler != null) {
894					handler.registerExitCode(exitCode);
895				}
896			}
897		}
