899		private int getExitCodeFromException(@Nullable ConfigurableApplicationContext context, Throwable exception) {
900			int exitCode = getExitCodeFromMappedException(context, exception);
901			if (exitCode == 0) {
902				exitCode = getExitCodeFromExitCodeGeneratorException(exception);
903			}
904			return exitCode;
905		}
906	
907		private int getExitCodeFromMappedException(@Nullable ConfigurableApplicationContext context, Throwable exception) {
908			if (context == null || !context.isActive()) {
909				return 0;
910			}
911			ExitCodeGenerators generators = new ExitCodeGenerators();
912			Collection<ExitCodeExceptionMapper> beans = context.getBeansOfType(ExitCodeExceptionMapper.class).values();
913			generators.addAll(exception, beans);
914			return generators.getExitCode();
915		}
916	
917		private int getExitCodeFromExitCodeGeneratorException(@Nullable Throwable exception) {
918			if (exception == null) {
919				return 0;
920			}
921			if (exception instanceof ExitCodeGenerator generator) {
922				return generator.getExitCode();
923			}
924			return getExitCodeFromExitCodeGeneratorException(exception.getCause());
925		}
