1389		/**
1390		 * Static helper that can be used to exit a {@link SpringApplication} and obtain a
1391		 * code indicating success (0) or otherwise. Does not throw exceptions but should
1392		 * print stack traces of any encountered. Applies the specified
1393		 * {@link ExitCodeGenerator ExitCodeGenerators} in addition to any Spring beans that
1394		 * implement {@link ExitCodeGenerator}. When multiple generators are available, the
1395		 * first non-zero exit code is used. Generators are ordered based on their
1396		 * {@link Ordered} implementation and {@link Order @Order} annotation.
1397		 * @param context the context to close if possible
1398		 * @param exitCodeGenerators exit code generators
1399		 * @return the outcome (0 if successful)
1400		 */
1401		public static int exit(ApplicationContext context, ExitCodeGenerator... exitCodeGenerators) {
1402			Assert.notNull(context, "'context' must not be null");
1403			int exitCode = 0;
1404			try {
1405				try {
1406					ExitCodeGenerators generators = new ExitCodeGenerators();
1407					Collection<ExitCodeGenerator> beans = context.getBeansOfType(ExitCodeGenerator.class).values();
1408					generators.addAll(exitCodeGenerators);
1409					generators.addAll(beans);
1410					exitCode = generators.getExitCode();
1411					if (exitCode != 0) {
1412						context.publishEvent(new ExitCodeEvent(context, exitCode));
1413					}
1414				}
1415				finally {
1416					close(context);
1417				}
1418			}
1419			catch (Exception ex) {
1420				ex.printStackTrace();
1421				exitCode = (exitCode != 0) ? exitCode : 1;
1422			}
1423			return exitCode;
1424		}
