1700		/**
1701		 * Starts a non-daemon thread to keep the JVM alive on {@link ContextRefreshedEvent}.
1702		 * Stops the thread on {@link ContextClosedEvent}.
1703		 */
1704		private static final class KeepAlive implements ApplicationListener<ApplicationContextEvent> {
1705	
1706			private final AtomicReference<@Nullable Thread> thread = new AtomicReference<>();
1707	
1708			@Override
1709			public void onApplicationEvent(ApplicationContextEvent event) {
1710				if (event instanceof ContextRefreshedEvent) {
1711					startKeepAliveThread();
1712				}
1713				else if (event instanceof ContextClosedEvent) {
1714					stopKeepAliveThread();
1715				}
1716			}
1717	
1718			private void startKeepAliveThread() {
1719				Thread thread = new Thread(() -> {
1720					while (true) {
1721						try {
1722							Thread.sleep(Long.MAX_VALUE);
1723						}
1724						catch (InterruptedException ex) {
1725							break;
1726						}
1727					}
1728				});
1729				if (this.thread.compareAndSet(null, thread)) {
1730					thread.setDaemon(false);
1731					thread.setName("keep-alive");
1732					thread.start();
1733				}
1734			}
1735	
1736			private void stopKeepAliveThread() {
1737				Thread thread = this.thread.getAndSet(null);
1738				if (thread == null) {
1739					return;
1740				}
1741				thread.interrupt();
1742			}
1743	
1744		}
