44	/**
45	 * {@link ReactiveWebServerFactory} that can be used to create {@link NettyWebServer}s.
46	 *
47	 * @author Brian Clozel
48	 * @author Moritz Halbritter
49	 * @author Scott Frederick
50	 * @since 4.0.0
51	 */
52	public class NettyReactiveWebServerFactory extends AbstractReactiveWebServerFactory {
53	
54		private Set<NettyServerCustomizer> serverCustomizers = new LinkedHashSet<>();
55	
56		private final List<NettyRouteProvider> routeProviders = new ArrayList<>();
57	
58		private @Nullable Duration lifecycleTimeout;
59	
60		private boolean useForwardHeaders;
61	
62		private @Nullable ReactorResourceFactory resourceFactory;
63	
64		public NettyReactiveWebServerFactory() {
65		}
66	
67		public NettyReactiveWebServerFactory(int port) {
68			super(port);
69		}
70	
71		@Override
72		public WebServer getWebServer(HttpHandler httpHandler) {
73			HttpServer httpServer = createHttpServer();
74			ReactorHttpHandlerAdapter handlerAdapter = new ReactorHttpHandlerAdapter(httpHandler);
75			NettyWebServer webServer = createNettyWebServer(httpServer, handlerAdapter, this.lifecycleTimeout,
76					getShutdown());
77			webServer.setRouteProviders(this.routeProviders);
78			return webServer;
79		}
80	
81		NettyWebServer createNettyWebServer(HttpServer httpServer, ReactorHttpHandlerAdapter handlerAdapter,
82				@Nullable Duration lifecycleTimeout, Shutdown shutdown) {
83			return new NettyWebServer(httpServer, handlerAdapter, lifecycleTimeout, shutdown, this.resourceFactory);
84		}
85	
86		/**
87		 * Returns a mutable collection of the {@link NettyServerCustomizer}s that will be
88		 * applied to the Netty server builder.
89		 * @return the customizers that will be applied
90		 */
91		public Collection<NettyServerCustomizer> getServerCustomizers() {
92			return this.serverCustomizers;
93		}
94	
95		/**
96		 * Set {@link NettyServerCustomizer}s that should be applied to the Netty server
97		 * builder. Calling this method will replace any existing customizers.
98		 * @param serverCustomizers the customizers to set
99		 */
100		public void setServerCustomizers(Collection<? extends NettyServerCustomizer> serverCustomizers) {
101			Assert.notNull(serverCustomizers, "'serverCustomizers' must not be null");
102			this.serverCustomizers = new LinkedHashSet<>(serverCustomizers);
103		}
104	
105		/**
106		 * Add {@link NettyServerCustomizer}s that should be applied while building the
107		 * server.
108		 * @param serverCustomizers the customizers to add
109		 */
110		public void addServerCustomizers(NettyServerCustomizer... serverCustomizers) {
111			Assert.notNull(serverCustomizers, "'serverCustomizers' must not be null");
112			this.serverCustomizers.addAll(Arrays.asList(serverCustomizers));
113		}
114	
115		/**
116		 * Add {@link NettyRouteProvider}s that should be applied, in order, before the
117		 * handler for the Spring application.
118		 * @param routeProviders the route providers to add
119		 */
120		public void addRouteProviders(NettyRouteProvider... routeProviders) {
121			Assert.notNull(routeProviders, "'routeProviders' must not be null");
122			this.routeProviders.addAll(Arrays.asList(routeProviders));
123		}
124	
125		/**
126		 * Set the maximum amount of time that should be waited when starting or stopping the
127		 * server.
128		 * @param lifecycleTimeout the lifecycle timeout
129		 */
130		public void setLifecycleTimeout(@Nullable Duration lifecycleTimeout) {
131			this.lifecycleTimeout = lifecycleTimeout;
132		}
133	
134		/**
135		 * Set if x-forward-* headers should be processed.
136		 * @param useForwardHeaders if x-forward headers should be used
137		 */
138		public void setUseForwardHeaders(boolean useForwardHeaders) {
139			this.useForwardHeaders = useForwardHeaders;
140		}
141	
142		/**
143		 * Set the {@link ReactorResourceFactory} to get the shared resources from.
144		 * @param resourceFactory the server resources
145		 */
146		public void setResourceFactory(@Nullable ReactorResourceFactory resourceFactory) {
147			this.resourceFactory = resourceFactory;
148		}
149	
150		private HttpServer createHttpServer() {
151			HttpServer server = HttpServer.create().bindAddress(this::getListenAddress);
152			Ssl ssl = getSsl();
153			if (Ssl.isEnabled(ssl)) {
154				server = customizeSslConfiguration(server, ssl);
155			}
156			if (getCompression() != null && getCompression().getEnabled()) {
157				CompressionCustomizer compressionCustomizer = new CompressionCustomizer(getCompression());
158				server = compressionCustomizer.apply(server);
159			}
160			server = server.protocol(listProtocols()).forwarded(this.useForwardHeaders);
161			return applyCustomizers(server);
162		}
163	
164		private HttpServer customizeSslConfiguration(HttpServer httpServer, Ssl ssl) {
165			SslServerCustomizer customizer = new SslServerCustomizer(getHttp2(), ssl.getClientAuth(), getSslBundle(),
166					getServerNameSslBundles());
167			addBundleUpdateHandler(null, ssl.getBundle(), customizer);
168			ssl.getServerNameBundles()
169				.forEach((serverNameSslBundle) -> addBundleUpdateHandler(serverNameSslBundle.serverName(),
170						serverNameSslBundle.bundle(), customizer));
171			return customizer.apply(httpServer);
172		}
173	
174		private void addBundleUpdateHandler(@Nullable String serverName, @Nullable String bundleName,
175				SslServerCustomizer customizer) {
176			if (StringUtils.hasText(bundleName)) {
177				SslBundles sslBundles = getSslBundles();
178				Assert.state(sslBundles != null, "'sslBundles' must not be null");
179				sslBundles.addBundleUpdateHandler(bundleName,
180						(sslBundle) -> customizer.updateSslBundle(serverName, sslBundle));
181			}
182		}
183	
184		private HttpProtocol[] listProtocols() {
185			List<HttpProtocol> protocols = new ArrayList<>();
186			protocols.add(HttpProtocol.HTTP11);
187			if (getHttp2() != null && getHttp2().isEnabled()) {
188				if (getSsl() != null && getSsl().isEnabled()) {
189					protocols.add(HttpProtocol.H2);
190				}
191				else {
192					protocols.add(HttpProtocol.H2C);
193				}
194			}
195			return protocols.toArray(new HttpProtocol[0]);
196		}
197	
198		private InetSocketAddress getListenAddress() {
199			if (getAddress() != null) {
200				return new InetSocketAddress(getAddress().getHostAddress(), getPort());
201			}
202			return new InetSocketAddress(getPort());
203		}
204	
205		private HttpServer applyCustomizers(HttpServer server) {
206			for (NettyServerCustomizer customizer : this.serverCustomizers) {
207				server = customizer.apply(server);
208			}
209			return server;
210		}
211	
212	}
